<button class="sidebar-mask" type="button" aria-label="Close navigation" hidden></button>
<div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu icon-button" type="button" aria-label="Open navigation" aria-controls="admin-sidebar" aria-expanded="false"><?= listingIcon('filter') ?></button><span>Workspace <b>/</b> <strong><?= e($title) ?></strong></span></div><div class="top-actions"><button class="theme-button icon-button" type="button" aria-label="Switch to dark mode" aria-pressed="false"><span aria-hidden="true">☾</span></button><a class="visit-site" href="../">Visit website &nearr;</a><div class="avatar" aria-label="Royalmark workspace">RM</div></div></header>
