<section class="panel inventory"><div class="panel-title"><div><h2><?= $view==='overview'?'Property overview':'Property inventory' ?></h2><p><?= count($filtered) ?> sample listings <?= $query!==''||$purpose!==''?'matching your filters':'' ?></p></div><a class="text-link" href="../property-listing">View website listings &nearr;</a></div><form class="table-toolbar" method="get" action="./"><input type="hidden" name="view" value="<?= e($view) ?>"><label class="search-field"><?= listingIcon('search') ?><span class="sr-only">Search properties</span><input name="q" type="search" placeholder="Search properties or city..." value="<?= e($query) ?>"></label><label><span class="sr-only">Listing purpose</span><select name="purpose"><option value="">All listings</option><?php foreach(['Rent','Sell'] as $option): ?><option <?= $purpose===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><button class="primary-button" type="submit">Filter</button><?php if($query!==''||$purpose!==''): ?><a class="text-link" href="./?view=<?= e($view) ?>">Reset</a><?php endif; ?></form><div class="table-scroll" tabindex="0" role="region" aria-label="Properties table"><table><thead><tr><th>Property</th><th>Location</th><th>Type</th><th>Purpose</th><th>Price</th><th><span class="sr-only">Details</span></th></tr></thead><tbody><?php foreach($filtered as $property): ?><tr><td><div class="property-cell"><img src="../<?= e(substr($property['image'],2)) ?>" alt="" width="58" height="48" loading="lazy"><div><strong><?= e($property['title']) ?></strong><span><?= $property['beds'] ?> beds · <?= number_format($property['area']) ?> sq.ft<?php if($property['featured']): ?> · Featured<?php endif; ?></span></div></div></td><td><?= e($property['city']) ?></td><td><?= e($property['type']) ?></td><td><span class="purpose-badge <?= $property['purpose']==='Rent'?'rent':'sale' ?>"><?= e($property['purpose']==='Sell'?'For sale':'For rent') ?></span></td><td class="price-cell"><?= e(listingPrice($property)) ?><?php if($property['purpose']==='Rent'): ?><small>/ month</small><?php endif; ?></td><td><a class="detail-link" href="../property.php?slug=<?= rawurlencode($property['slug']) ?>" aria-label="View <?= e($property['title']) ?>">&nearr;</a></td></tr><?php endforeach; ?><?php if(!$filtered): ?><tr><td colspan="6" class="empty-state">No properties match your filters. Try another search or reset filters.</td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?><section class="panel project-preview"><div class="panel-title"><div><h2>Project showcase</h2><p>Illustrative concepts, not live development announcements</p></div><a class="text-link" href="../projects">Open projects &nearr;</a></div><div class="admin-project-grid"><?php foreach([['Royal Gardens','Under construction',65,'sunrise-3bhk-apartment'],['Lakeview Residences','Completed',100,'lakeview-2bhk-flat'],['Seaside Living','Upcoming',0,'bandra-sea-view-apartment']] as $project): ?><article><img src="../assets/properties/<?= e($project[3]) ?>.png" alt="Illustrative project cover" width="512" height="340"><div><span class="subtle-tag"><?= e($project[1]) ?></span><h3><?= e($project[0]) ?></h3><label>Sample progress <strong><?= $project[2] ?>%</strong><progress max="100" value="<?= $project[2] ?>"><?= $project[2] ?>%</progress></label><a class="text-link" href="../projects?q=<?= rawurlencode($project[0]) ?>">View project &rarr;</a></div></article><?php endforeach; ?></div></section><?php endif; ?>
